import 'package:flutter/material.dart';
import '../app.dart';
import '../state/app_state.dart';
class HomeScreen extends StatelessWidget { const HomeScreen({super.key}); @override Widget build(BuildContext context){ final state=AppScope.of(context); final trainer=state.role==AppRole.trainer; final modules=trainer?_trainerModules:_memberModules; return Scaffold(appBar: AppBar(title: Text(trainer?'Trainer App':'Member App')), body: ListView(padding: const EdgeInsets.all(16), children:[ Text(trainer?'Coach clients and manage bookings':'Track workouts, attendance, nutrition, and purchases', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height:16), for(final m in modules) Card(child: ListTile(leading: Icon(m.icon), title: Text(m.title), subtitle: Text(m.subtitle), trailing: const Icon(Icons.chevron_right), onTap:()=>Navigator.pushNamed(context,m.route,arguments:m.title))) ])); }}
class MobileModule { const MobileModule(this.title,this.subtitle,this.icon,this.route); final String title; final String subtitle; final IconData icon; final String route; }
const _memberModules=[MobileModule('Dashboard','Gym overview and key metrics',Icons.dashboard,'/dashboard'),MobileModule('QR Attendance','Scan branch QR codes and view visits',Icons.qr_code,'/qr-attendance'),MobileModule('Memberships','Renew plans and view invoices',Icons.card_membership,'/module'),MobileModule('Workouts','Assigned workout programs',Icons.fitness_center,'/module'),MobileModule('Nutrition','Meal plans and macros',Icons.restaurant,'/module'),MobileModule('AI Posture','Analyze demo posture frames',Icons.camera_alt,'/posture-capture'),MobileModule('Store','Buy products and supplements',Icons.store,'/module'),MobileModule('Payments','Razorpay checkout history',Icons.payment,'/razorpay-checkout'),MobileModule('WhatsApp','Renewal and booking alerts',Icons.chat,'/module')];
const _trainerModules=[MobileModule('Dashboard','Gym overview and key metrics',Icons.dashboard,'/dashboard'),MobileModule('Trainer Bookings','Manage PT sessions',Icons.calendar_month,'/module'),MobileModule('Client Workouts','Assign programs',Icons.fitness_center,'/module'),MobileModule('Client Nutrition','Review meal plans',Icons.restaurant,'/module'),MobileModule('AI Posture','Review posture analysis',Icons.camera_alt,'/posture-capture'),MobileModule('Progress','Track member outcomes',Icons.show_chart,'/module'),MobileModule('WhatsApp','Send coaching reminders',Icons.chat,'/module')];
